  idea: { title: "Три группы и их работа", intro: "Белки, жиры и углеводы называют макронутриентами: они нужны в больших количествах и дают энергию. Витамины и минералы нужны в малых количествах и энергии не дают.", points: [
    ["Белки: строительный материал", "Из них состоят мышцы, кожа, ферменты и многие гормоны. Источники: рыба, птица, мясо, яйца, молочные продукты, бобовые, орехи. Белковая еда хорошо насыщает."],
    ["Жиры: запас и защита", "Жиры входят в оболочку каждой клетки и нужны для усвоения витаминов A, D, E и K. Ненасыщенные жиры из рыбы, орехов и растительных масел полезны. Насыщенные из жирного мяса и сливочного масла стоит ограничивать, а промышленных трансжиров избегать."],
    ["Углеводы: основное топливо", "Главный источник энергии, в том числе для мозга. Цельные крупы, овощи, бобовые и фрукты дают энергию постепенно и содержат клетчатку. Сахар и сладкие напитки дают её быстро и больше ничего не приносят."],
    ["Клетчатка", "Часть растительной пищи, которая не переваривается, но нужна для работы кишечника и дольше сохраняет сытость. Её много в овощах, бобовых и цельных крупах."],
    ["Ориентиры ВОЗ", "Всемирная организация здравоохранения советует взрослым съедать не меньше 400 граммов овощей и фруктов в день, ограничивать добавленный сахар и держаться в пределах 5 граммов соли в день. Это примерно чайная ложка."] ],
    callout: "Вопрос к любому продукту: что в нём кроме энергии? Цельные продукты приносят белок, клетчатку и витамины. Сладости и снеки в основном только энергию." },
  example: { title: "Кейс: почему через два часа снова хочется есть", text: [
    "Марат обедает на бегу: сладкий чай, белая булка с колбасой, шоколадный батончик. По ощущениям он съел много, но к четырём часам снова голоден, тянет на сладкое и клонит в сон.",
    "В его обеде много быстрых углеводов и насыщенного жира. Мало белка, почти нет клетчатки. Такая еда быстро усваивается, и сытость быстро уходит.",
    "Он меняет обед: гречка, кусок курицы, салат из свежих овощей с растительным маслом, чай без сахара. Объём примерно тот же. Теперь в обеде есть белок, медленные углеводы с клетчаткой и ненасыщенный жир. Сытости хватает до вечера, и батончик в четыре часа уже не нужен." ],
    takeaway: "Марат не стал есть меньше и ничего себе не запретил. Он поменял источники: вместо сахара и белой муки появились крупа, овощи и белок." },
  practice: { title: "Разберите свой обычный день", intro: "Вспомните, что вы ели вчера, или запишите сегодняшнюю еду. Взвешивать и считать ничего не нужно.", steps: [
    "Запишите приёмы пищи и перекусы. Рядом с каждым продуктом отметьте, что в нём главное: белок, жир или углеводы.",
    "Посмотрите, в каком приёме пищи почти нет белка и где нет овощей. Обычно это завтрак и перекусы.",
    "Возьмите с полки один привычный продукт в упаковке и прочитайте состав: сколько в нём сахара и соли на сто граммов и что стоит в списке первым." ],
    reflect: "Какая группа преобладает в вашей еде? Какую одну замену было бы легко сделать уже завтра?" },
  check: [
    { q: "Зачем организму жиры?", options: ["Они не нужны, их лучше исключить", "Они входят в оболочки клеток и помогают усваивать часть витаминов", "Они нужны только для запаса энергии на зиму"], correct: 1, why: "Жиры — часть каждой клетки, и без них не усваиваются витамины A, D, E и K. Важен источник: предпочтительны ненасыщенные." },
    { q: "Чем цельная крупа отличается от сахара как источник углеводов?", options: ["Она даёт энергию постепенно и содержит клетчатку", "В ней нет углеводов", "Она усваивается быстрее"], correct: 0, why: "И то и другое углеводы, но цельные продукты усваиваются медленнее и приносят клетчатку, витамины и минералы." },
    { q: "Сколько овощей и фруктов в день советует взрослым ВОЗ?", options: ["Не больше 100 граммов", "Ровно один килограмм", "Не меньше 400 граммов"], correct: 2, why: "Рекомендация ВОЗ — не меньше 400 граммов в день. Картофель и другие крахмалистые корнеплоды в этот счёт не входят." } ],
  key: { title: "Нужны все три, важен источник", theses: ["Белки строят, жиры защищают и помогают усваивать витамины, углеводы дают энергию.", "Внутри каждой группы есть более и менее полезные источники.", "Цельные продукты приносят не только энергию."], action: "Добавьте овощи и источник белка в тот приём пищи, где их обычно нет." },
